INSERT INTO appwrite_documents (database_id, collection_id, id, data_json, permissions_json, owner_id, created_at, updated_at, source_file, source_snapshot_at) VALUES ('lg', 'posts', '6a13d8a474d50d13cad0', '{"boardId":"main","title":"1","content":"111111111","authorId":"20240338","authorName":"20240338@campus.local","viewPermission":4,"targetGroups":["20240860"],"status":0,"editedAt":null}', '["update(\"user:20240338\")","delete(\"user:20240338\")","read(\"user:20240338\")","read(\"user:student_20240860\")"]', '20240338', '2026-05-25T05:05:40.479Z', '2026-05-25T05:05:40.479Z', 'LG-Site-Backup/backups/2026-week20.7142857142857/posts.json', NULL) ON CONFLICT(database_id, collection_id, id) DO UPDATE SET data_json=excluded.data_json, permissions_json=excluded.permissions_json, owner_id=excluded.owner_id, created_at=excluded.created_at, updated_at=excluded.updated_at, source_file=excluded.source_file, source_snapshot_at=excluded.source_snapshot_at WHERE excluded.updated_at >= appwrite_documents.updated_at;
INSERT INTO appwrite_documents (database_id, collection_id, id, data_json, permissions_json, owner_id, created_at, updated_at, source_file, source_snapshot_at) VALUES ('lg', 'posts', '6a368f3d055a45157ddd', '{"boardId":"main","title":"我不想「息事宁人」","content":"之前我跟朋友们的控诉说认为「跟老师亲近的大多是女生」结果这周的sm（神秘）事件确实有力的打破了我的认知（ber男娘？）我着实没想到会有人不顾一切代价背刺同学以达到自己的目的的（谄媚老师？）\n\n他妈的众所周知但凡有人给人讲的秘密，TM是个人都知道什么叫「保守秘密」可能是鄙人不才，鄙人实在想不出为什么要如此的「泄露秘密」是为了什么，关键这TM不是第一次了，之前你背刺的时候，我们甚至猜测你是西方树叶TMD吸多了。TMD除非你说我是吴\n彦祖我或许还会让说这是啥阴！还有凌\n晨TMD你自己讲话在那吵什么吵！你是在这找什么存在感？TM我们熟吗？狗天天在那叫叫叫我们都不爽了，你TMD装逼干嘛呢！自己干了啥事不知道吗！\n\n说回原题，你TM的说了就说了，至少给我拿出一点态度吧（装死，老传统了）你告诉我什么叫「我之前就说了一句」什么叫「那一次忘了」（依旧超绝记忆），你再告诉我什么叫「我可能说过但我忘了」（依旧奇特的海马体构造）在证人的证据下，某人也是成功地在认错和反驳之间选择了「人身攻击」（人参公鸡，大补），你自己能给出合理的解释吗？可能是鄙人才疏学浅，鄙人实在不敢相信为什么一个八竿子打不着的矛盾要找宿管解决（芳芳～），鄙人依旧不才，实在不理解为什么别的时候你马马虎虎，跑操的那一声却记得如此酣畅淋漓（可能是鄙人大脑构造与你“稍微”有亿点不同罢）\n\n或许你是真的「bu xiao xin」说的，鄙人认为一句「dui bu qi」是有必要的，可能是鄙人听觉系统与你语言不匹配，我实在听不到你哪怕一句「人类说的」道歉，或者是说我们要什么「互相道歉」，因为什么「就当我说了，我道歉」，和「但你污蔑了我，你道歉」鄙人实在无法理解你那超脱三界之外不在五行之中的脑回路，这大概是唯一的谈判——\n呃......啊不！有一句——什么“呃，虽然我没说，或者是虽然我不知道我说了，但既然证人说我说了，那就当我说了吧，基于这个猜测，跟你道歉”鄙人心胸狭隘，十分期待你用「同款表述」跟老师或者是老妈道歉，也衷心祝愿你接受道歉时遇到的都是这样的超绝雷霆状语（阿弥陀佛～佛祖保佑你～）\n\n之前我抱怨过有人跟老师蛐蛐别人，这周，我也是再次刷新了认知（眼界+1）：怎么某人把老师当成自己在学校的妈妈们啊（666打瓦认识的）不占理，鄙人认为是要去解决问题，可能鄙人这一方面经验不足，鄙人不认为解决问题的最好方式是跟自己的妈妈们倾诉，然后又屁颠屁颠地去找老师，哭的声泪俱下，尝试「解决提出问题的人」在同学间找不到的「公道」 ，鄙人认为在老师那和老妈那一样找不到（不然受委屈了直接打瓦解决一切问题），放心，不管是你的爸爸妈妈来学校（或者是爸爸妈妈们）都只会把事情闹大罢了，鄙人认为像这种行为，在现在叫「背刺行为」，在1946年，大概是叫「特务行为」罢（不兑就是特务）\n\n1945年，美国在日本广岛和长崎投下了两枚原子弹，加速了反法西斯战争的胜利，但此后的日媒开始借题炒作所谓“日本是二战中最大受害者”，企图混淆视听，受到其他人的支持，殊不知是牠们罪有应得，这不过就是军国主义灭亡前的呓语罢了\n\n某人也一样","authorId":"student_20240307","authorName":"20240307","viewPermission":1,"targetGroups":[],"status":0,"editedAt":null}', '[]', 'student_20240307', '2026-06-20T13:01:49.022Z', '2026-06-20T13:01:49.022Z', 'LG-Site-Backup/backups/last/posts.json', NULL) ON CONFLICT(database_id, collection_id, id) DO UPDATE SET data_json=excluded.data_json, permissions_json=excluded.permissions_json, owner_id=excluded.owner_id, created_at=excluded.created_at, updated_at=excluded.updated_at, source_file=excluded.source_file, source_snapshot_at=excluded.source_snapshot_at WHERE excluded.updated_at >= appwrite_documents.updated_at;
